outputs.yaml:
# SECS 2 calibration -> CamillaDSP v4 (generated)
# inputs 12: L, R, C, Ls, Rs, Lb, Rb, Tfl, Tfr, Tbl, Tbr, LFE / outputs 14: L, R, C, Ls, Rs, Lb, Rb, Tfl, Tfr, Tbl, Tbr, SW1, SW2, SW3
# mode mixed, total latency 8.0 ms, RC upper 500 Hz; no MIMO
# LFE: gain +10 dB, LR24 lowpass 120 Hz -> every sub bus (same sub gain/polarity/filters/delay as the bass-managed mains), no MIMO
# sub SW1: auto gain -10.305 dB, delay 21.288 ms, polarity inverted
# sub SW2: auto gain -10.280 dB, delay 11.502 ms, polarity normal
# sub SW3: auto gain -15.653 dB, delay 2.122 ms, polarity normal
#
# ---- HOW TO USE (CamillaDSP 4.1.x + CamillaGUI 4.1) ----
# 1) Files: this file goes to camilladsp/configs, the wav files to camilladsp/coeffs
#    (same layout as this export). CamillaGUI: Files tab, upload the wav files under Filters FIRST,
#    then this file under Configs. FIR paths are relative to this file (../coeffs/...).
# 2) Devices: capture/playback below are FILE placeholders (in.raw / out.raw) - change them:
#    capture = loopback (Windows: Wasapi "CABLE Output (VB-Audio Virtual Cable)", Mac: CoreAudio
#    "BlackHole 16ch"), playback = your audio interface. format: empty or F32 (F32_LE is for files only).
#    samplerate 48000 (Windows: set both devices' default format to 48000 Hz too).
#    Different clocks (loopback -> interface): enable_rate_adjust; Windows also resampler AsyncSinc.
#    Capture channels = route_in "in", playback channels = route_out "out".
# 3) Channel numbers start at 0 (interface output 1 = 0). Default routing is 1:1:
#    ch  input (capture -> route_in)   output (route_out -> playback)
#     0  L                               L
#     1  R                               R
#     2  C                               C
#     3  Ls                              Ls
#     4  Rs                              Rs
#     5  Lb                              Lb
#     6  Rb                              Rb
#     7  Tfl                             Tfl
#     8  Tfr                             Tfr
#     9  Tbl                             Tbl
#    10  Tbr                             Tbr
#    11  LFE                             SW1
#    12  -                               SW2
#    13  -                               SW3
#    To move a channel change only the Mixers route_in (source "channel") or route_out ("dest").
#    More interface outputs: raise route_out "out" and the playback channels to the same number.
#    Players send LFE 4th (Windows 7.1: FL FR FC LFE BL BR SL SR) - reorder them in route_in.
# 4) Latency: filters 8.0 ms (mode mixed) + CamillaDSP buffering (grows with chunksize).
#    Video: set the player audio delay to about -8 ms (plus the buffering) to keep lip sync.
title: "SECS 2 mixed (8.0 ms)"
description: "inputs 0 L, 1 R, 2 C, 3 Ls, 4 Rs, 5 Lb, 6 Rb, 7 Tfl, 8 Tfr, 9 Tbl, 10 Tbr, 11 LFE | outputs 0 L, 1 R, 2 C, 3 Ls, 4 Rs, 5 Lb, 6 Rb, 7 Tfl, 8 Tfr, 9 Tbl, 10 Tbr, 11 SW1, 12 SW2, 13 SW3 | numbers start at 0, change routing in Mixers route_in / route_out | devices are file placeholders: set capture = loopback, playback = interface"
devices:
  samplerate: 48000
  chunksize: 1024
  capture: {"type": "RawFile", "filename": "{OUT}/in.raw", "format": "F32_LE", "channels": 12, "extra_samples": 96000}
  playback: {"type": "File", "filename": "{OUT}/out.raw", "format": "F32_LE", "channels": 14}
